    { t: "汽車前擋風玻璃放銀色遮陽板,車內就比較不會那麼熱。", b: 'rad',
      why: { s: "銀色板把太陽光反射回去。", f: "輻射:銀色表面反射大部分太陽輻射,減少進入車內的熱。" } },
    { t: "平底鍋放在瓦斯爐上,鍋子整個都熱了,連鍋邊也是。", b: 'cond',
      why: { s: "熱在鍋子的金屬裡傳開。", f: "傳導:鍋底受熱後,熱沿金屬傳到整個鍋身。" } },
    { t: "冬天把暖暖包握在手裡,手就暖了。", b: 'cond',
      why: { s: "暖暖包碰到手,熱直接傳過來。", f: "傳導:暖暖包與手掌接觸,熱由高溫的包傳到手。" } },
    { t: "鍋子上蓋著蓋子,蒸氣在蓋子內側凝成水珠往下滴。", b: 'conv',
      why: { s: "熱蒸氣往上跑碰到蓋子。", f: "對流:水蒸氣上升碰到較冷的鍋蓋凝結,是熱氣體上升的證據。" } },
    { t: "老鷹不用拍翅膀,靠著上升的熱氣流在天上盤旋。", b: 'conv',
      why: { s: "熱空氣上升把老鷹托起來。", f: "對流:地面受熱後熱空氣上升形成上升氣流,老鷹借力滑翔。" } },
    { t: "鐵匠把鐵燒到紅通通,站在旁邊就覺得臉很熱。", b: 'rad',
      why: { s: "燒紅的鐵放出熱輻射。", f: "輻射:高溫物體發出大量紅外線,不必接觸就能感覺到熱。" } },
    { t: "在雪地裡曬太陽,穿黑衣服的人比穿白衣服的先覺得暖。", b: 'rad',
      why: { s: "黑色吸熱快。", f: "輻射:深色吸收太陽輻射多,淺色反射多,所以夏天穿淺色比較涼。" } }
