  diff: 4,
  skills: ['音感', '節奏'],   /* ★ v1.4.0 加入演奏／拍子 */
  thumb: '力行走廊.png',
  bgm: 'bgm-avatar-card',   /* ★ v1.3.0 遊戲中 BGM(index.html 的 <audio id>,沿用主程式既有曲) */
